function useLS(key, def) {
  const [v, sv] = useState(() => { try { const x = localStorage.getItem(key); return x ? JSON.parse(x) : def; } catch { return def; } });
  const set = useCallback(fn => { sv(p => { const n = typeof fn === "function" ? fn(p) : fn; try { localStorage.setItem(key, JSON.stringify(n)); } catch {} return n; }); }, [key]);
  return [v, set];
}
 
const getLocalISO = (d = new Date()) => `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const td = () => getLocalISO();
const DSV = ["Sön","Mån","Tis","Ons","Tor","Fre","Lör"];
const MSV = ["jan","feb","mar","apr","maj","jun","jul","aug","sep","okt","nov","dec"];
const MFV = ["Januari","Februari","Mars","April","Maj","Juni","Juli","Augusti","September","Oktober","November","December"];
const fmt = d => { const x = new Date(d+"T12:00:00"); return `${x.getDate()} ${MSV[x.getMonth()]}`; };
const dSince = d => Math.max(0, Math.floor((new Date(td()+"T12:00:00") - new Date(d+"T12:00:00")) / 86400000));
const dUntil = d => Math.ceil((new Date(d+"T12:00:00") - new Date(td()+"T12:00:00")) / 86400000);
 
function weekDates(off = 0) {
  const d = new Date(); d.setHours(0,0,0,0);
  d.setDate(d.getDate() + (d.getDay()===0?-6:1-d.getDay()) + off*7);
  return Array.from({length:7}, (_,i) => { const x=new Date(d); x.setDate(x.getDate()+i); return x; });
}
function monthDates(y, m) {
  const first = new Date(y,m,1), last = new Date(y,m+1,0);
  const pad = first.getDay()===0?6:first.getDay()-1;
  const days = Array(pad).fill(null);
  for(let i=1;i<=last.getDate();i++) days.push(new Date(y,m,i));
  return days;
}
 
// XP system – configurable, stored in localStorage
const DEF_XPR = {task:20,training:35,checkin:15,milestone:50,steps:25,miss_training:-10,miss_deadline:-15,social_zero:-10};
const DEF_LEVELS = [
  {xp:0,   reward:"Kom igång! 🌱"},
  {xp:100, reward:"Välj en film att titta på 🎬"},
  {xp:250, reward:"Köp något gott 🍰"},
  {xp:500, reward:"En ledig dag – gör precis vad du vill!"},
  {xp:900, reward:"Ny klädesplagg 👗"},
  {xp:1500,reward:"Restaurangbesök 🍽️"},
  {xp:2400,reward:"Spa-dag eller massage 💆"},
  {xp:3700,reward:"En weekend-resa 🗺️"},
  {xp:5500,reward:"Stor dröm-belöning – bestäm själv! ⭐"},
];
function useXPRates() {
  const [rates,setRates]=useLS("xpRates",DEF_XPR);
  const [levels,setLevels]=useLS("xpLevels",DEF_LEVELS);
  return {rates,setRates,levels,setLevels};
}
const getLvl = (xp,levels) => { const ls=levels||DEF_LEVELS; for(let i=ls.length-1;i>=0;i--) if(xp>=ls[i].xp) return i+1; return 1; };
const xpProg = (xp,levels) => { const ls=levels||DEF_LEVELS,l=getLvl(xp,ls),p=ls[l-1]?.xp||0,n=ls[l]?.xp||ls[ls.length-1].xp; return Math.min(100,(xp-p)/Math.max(n-p,1)*100); };
const xpNext = (xp,levels) => { const ls=levels||DEF_LEVELS,l=getLvl(xp,ls); return l>=ls.length?null:ls[l]?.xp; };
 
function useXP() {
  const [xp, sx] = useLS("xp", 0);
  const [floats, sf] = useState([]);
  const [lvlMsg, slm] = useState(null);
  const {levels} = useXPRates();
  const earn = useCallback((amt, x=200, y=400) => {
    sx(p => {
      const n=Math.max(0,p+amt), pl=getLvl(p,levels), nl=getLvl(n,levels);
      if(nl>pl) { const lv=levels[nl-1]; setTimeout(()=>{slm(lv?.reward||`Nivå ${nl}!`);setTimeout(()=>slm(null),4000)},100); }
      return n;
    });
    const id = Date.now();
    sf(f=>[...f,{id,amt,x,y}]);
    setTimeout(()=>sf(f=>f.filter(x=>x.id!==id)),1400);
  },[sx,levels]);
  return {xp,earn,floats,lvlMsg,levels};
}
 
