// ── HOBBIES ───────────────────────────────────────────────────────────────────
function Hobbies({xp}) {
  const [hobbies,setHobbies]=useLS("hobbies",DEF_HOBBIES);
  const [sel,setSel]=useState(null);
  const [showNew,setShowNew]=useState(false);
  const [nh,setNh]=useState({name:"",emoji:"⭐",color:"#9B8EC4"});
  const [ns,setNs]=useState("");
  const [showStep,setShowStep]=useState(false);
  const [dragStep,setDragStep]=useState(null);
 
  function moveMilestone(hid, sid, dir) {
    const update = steps => {
      const arr=[...steps], idx=arr.findIndex(s=>s.id===sid), to=idx+dir;
      if(to<0||to>=arr.length) return steps;
      [arr[idx],arr[to]]=[arr[to],arr[idx]]; return arr;
    };
    setHobbies(p=>p.map(h=>h.id!==hid?h:{...h,steps:update(h.steps)}));
    setSel(p=>p?{...p,steps:update(p.steps)}:p);
  }
 
  function handleStepDrop(hid,targetSid) {
    if(dragStep===targetSid) return;
    setHobbies(p=>p.map(h=>{
      if(h.id!==hid) return h;
      const s=[...h.steps],from=s.findIndex(x=>x.id===dragStep),to=s.findIndex(x=>x.id===targetSid);
      if(from<0||to<0) return h;
      const [item]=s.splice(from,1); s.splice(to,0,item); return {...h,steps:s};
    }));
    setSel(p=>{if(!p)return p; const s=[...p.steps],from=s.findIndex(x=>x.id===dragStep),to=s.findIndex(x=>x.id===targetSid); if(from<0||to<0) return p; const [item]=s.splice(from,1); s.splice(to,0,item); return {...p,steps:s};});
    setDragStep(null);
  }
 
  function toggle(hid,sid,e) {
    const h=hobbies.find(x=>x.id===hid),st=h?.steps.find(x=>x.id===sid);
    if(st&&!st.done) xp.earn(50,e.clientX,e.clientY);
    setHobbies(p=>p.map(h=>h.id!==hid?h:{...h,steps:h.steps.map(s=>s.id===sid?{...s,done:!s.done}:s)}));
    setSel(p=>p?{...p,steps:p.steps.map(s=>s.id===sid?{...s,done:!s.done}:s)}:p);
  }
  function addHobby() {
    if(!nh.name) return;
    setHobbies(p=>[...p,{id:`h${Date.now()}`,name:nh.name,emoji:nh.emoji,color:nh.color,steps:[{id:1,label:"Prova för första gången!",done:false}],levels:["Nybörjare","Lärling","Kompetent","Avancerad","Expert"]}]);
    setNh({name:"",emoji:"⭐",color:"#9B8EC4"});setShowNew(false);
  }
  function addStep(hid) {
    if(!ns.trim()) return;
    const step={id:Date.now(),label:ns.trim(),done:false};
    setHobbies(p=>p.map(h=>h.id!==hid?h:{...h,steps:[...h.steps,step]}));
    setSel(p=>p?{...p,steps:[...p.steps,step]}:p);
    setNs("");setShowStep(false);
  }
 
  if(sel) {
    const hobby=hobbies.find(h=>h.id===sel.id)||sel;
    const dc=hobby.steps.filter(s=>s.done).length;
    const lvls=hobby.levels||["Nybörjare","Lärling","Kompetent","Avancerad","Expert"];
    const li=Math.min(Math.floor(dc/Math.max(hobby.steps.length,1)*lvls.length),lvls.length-1);
    return <div style={{padding:"22px 18px"}}>
      <button onClick={()=>{setSel(null);setShowStep(false);}} style={{background:"none",border:"none",color:"var(--mu)",fontSize:14,cursor:"pointer",marginBottom:18,fontWeight:700}}>← Tillbaka</button>
      <div style={{display:"flex",alignItems:"center",gap:15,marginBottom:14}}>
        <div style={{width:62,height:62,borderRadius:19,background:hobby.color+"22",display:"flex",alignItems:"center",justifyContent:"center",fontSize:32,border:`2px solid ${hobby.color}33`}}>{hobby.emoji}</div>
        <div style={{flex:1}}>
          <div style={{fontFamily:"var(--fd)",fontWeight:900,fontSize:24}}>{hobby.name}</div>
          <Badge label={lvls[li]} color={hobby.color}/>
        </div>
        <button onClick={()=>{setHobbies(p=>p.filter(h=>h.id!==hobby.id));setSel(null);}} style={{background:"none",border:"none",color:"var(--mul)",cursor:"pointer",fontSize:20}}>🗑</button>
      </div>
 
      {/* XP Widget – only here in Hobbies! */}
      <XPWidget xp={xp.xp} levels={xp.levels}/>
 
      <Card style={{marginBottom:18}}>
        <div style={{display:"flex",justifyContent:"space-between",marginBottom:7}}><span style={{fontWeight:700}}>Framsteg</span><span style={{fontSize:13,color:"var(--mu)"}}>{dc}/{hobby.steps.length}</span></div>
        <Bar done={dc} total={Math.max(hobby.steps.length,1)} color={hobby.color} h={10}/>
        <div style={{display:"flex",gap:4,marginTop:9}}>
          {lvls.map((l,i)=><div key={l} style={{flex:1,textAlign:"center",fontSize:9,fontWeight:800,padding:"3px 1px",borderRadius:7,background:i<=li?hobby.color+"22":"var(--bd)",color:i<=li?hobby.color:"var(--mul)",border:`1.5px solid ${i<=li?hobby.color+"44":"transparent"}`}}>{l}</div>)}
        </div>
      </Card>
 
      <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:11}}>
        <div style={{fontFamily:"var(--fd)",fontWeight:800,fontSize:14}}>Milstolpar</div>
        <Btn sm onClick={()=>setShowStep(b=>!b)} color={hobby.color}>+ Milstolpe</Btn>
      </div>
      {showStep&&<div style={{display:"flex",gap:7,marginBottom:11}}>
        <input value={ns} onChange={e=>setNs(e.target.value)} placeholder="Ny milstolpe..." onKeyDown={e=>e.key==="Enter"&&addStep(hobby.id)}/>
        <Btn onClick={()=>addStep(hobby.id)} color={hobby.color}>Lägg till</Btn>
      </div>}
      {hobby.steps.map((step,i)=>{
        const locked=i>0&&!hobby.steps[i-1].done&&!step.done;
        return <div key={step.id} style={{display:"flex",alignItems:"center",gap:7,marginBottom:9}}>
          <div style={{display:"flex",flexDirection:"column",gap:2,flexShrink:0}}>
            <button onClick={()=>moveMilestone(hobby.id,step.id,-1)} disabled={i===0} style={{background:"none",border:"none",fontSize:13,cursor:i===0?"not-allowed":"pointer",color:"var(--mu)",lineHeight:1,opacity:i===0?.3:1,padding:"2px 4px"}}>▲</button>
            <button onClick={()=>moveMilestone(hobby.id,step.id,1)} disabled={i===hobby.steps.length-1} style={{background:"none",border:"none",fontSize:13,cursor:i===hobby.steps.length-1?"not-allowed":"pointer",color:"var(--mu)",lineHeight:1,opacity:i===hobby.steps.length-1?.3:1,padding:"2px 4px"}}>▼</button>
          </div>
          <div
            draggable={!locked} onDragStart={()=>!locked&&setDragStep(step.id)} onDragOver={e=>e.preventDefault()} onDrop={()=>handleStepDrop(hobby.id,step.id)}
            onClick={e=>!locked&&toggle(hobby.id,step.id,e)}
            style={{background:step.done?hobby.color+"22":"var(--ca)",border:`2px solid ${step.done?hobby.color:"var(--bo)"}`,borderRadius:13,padding:"13px 17px",display:"flex",alignItems:"center",gap:13,cursor:locked?"not-allowed":"pointer",opacity:locked?.42:1,transition:"all .18s",boxShadow:"var(--sh)",flex:1}}>
            <div style={{color:"var(--mu)",fontSize:16}}>⋮⋮</div>
            <div style={{width:34,height:34,borderRadius:"50%",flexShrink:0,background:step.done?hobby.color:"var(--bd)",border:`2.5px solid ${step.done?hobby.color:locked?"var(--bo)":"var(--g)"}`,display:"flex",alignItems:"center",justifyContent:"center",fontSize:step.done?14:12,color:step.done?"#fff":locked?"var(--mul)":"var(--g)",fontWeight:900}}>
              {step.done?"✓":locked?"🔒":(i+1)}
            </div>
            <span style={{fontSize:14,flex:1,color:step.done?"var(--tx)":locked?"var(--mul)":"var(--tx)",fontWeight:step.done?700:500}}>{step.label}</span>
            {step.done&&<span style={{fontSize:15}}>⭐</span>}
          </div>
          <div style={{display:"flex",flexDirection:"column",gap:3}}>
            <button onClick={e=>{e.stopPropagation();const t=prompt("Redigera milstolpe:",step.label);if(t&&t.trim())setHobbies(p=>p.map(h=>h.id===hobby.id?{...h,steps:h.steps.map(s=>s.id===step.id?{...s,label:t.trim()}:s)}:h));}} style={{background:"none",border:"none",fontSize:13,cursor:"pointer",color:"var(--bl)"}}>✏️</button>
            <button onClick={e=>{e.stopPropagation();setHobbies(p=>p.map(h=>h.id===hobby.id?{...h,steps:h.steps.filter(s=>s.id!==step.id)}:h));}} style={{background:"none",border:"none",fontSize:13,cursor:"pointer",color:"var(--r)"}}>🗑</button>
          </div>
        </div>;
      })}
    </div>;
  }
 
  return <div style={{padding:"22px 18px"}}>
    <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:7}}>
      <div style={{fontFamily:"var(--fd)",fontWeight:900,fontSize:24}}>✨ Hobbies</div>
      <Btn sm onClick={()=>setShowNew(b=>!b)} color="var(--p)">+ Hobby</Btn>
    </div>
    <div style={{fontSize:12,color:"var(--mu)",marginBottom:14}}>Klättra mot Expert – nå dina milstolpar! 🌟</div>
    {showNew&&<Card style={{marginBottom:14}}>
      <div style={{fontFamily:"var(--fd)",fontWeight:800,fontSize:14,marginBottom:11}}>Ny hobby</div>
      <div style={{display:"flex",gap:7,marginBottom:7}}>
        <input value={nh.emoji} onChange={e=>setNh(h=>({...h,emoji:e.target.value}))} style={{width:58}} placeholder="Emoji"/>
        <input value={nh.name} onChange={e=>setNh(h=>({...h,name:e.target.value}))} placeholder="Namn" style={{flex:1}}/>
      </div>
      <div style={{display:"flex",gap:7,alignItems:"center",marginBottom:11}}>
        <span style={{fontSize:12,color:"var(--mu)"}}>Färg:</span>
        {["#6BAF8D","#9B8EC4","#E8A066","#6FA3C8","#E07878","#F5C518"].map(col=><button key={col} onClick={()=>setNh(h=>({...h,color:col}))} style={{width:22,height:22,borderRadius:"50%",background:col,border:`3px solid ${nh.color===col?"var(--tx)":"transparent"}`,cursor:"pointer"}}/>)}
      </div>
      <div style={{display:"flex",gap:7}}>
        <Btn onClick={addHobby} color="var(--p)" style={{flex:1,display:"flex",justifyContent:"center"}}>Skapa</Btn>
        <Btn onClick={()=>setShowNew(false)} color="var(--mu)" out sm>Avbryt</Btn>
      </div>
    </Card>}
    <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:13}}>
      {hobbies.map(h=>{
        const dc=h.steps.filter(s=>s.done).length;
        const lvls=h.levels||["Nybörjare","Lärling","Kompetent","Avancerad","Expert"];
        const li=Math.min(Math.floor(dc/Math.max(h.steps.length,1)*lvls.length),lvls.length-1);
        return <Card key={h.id} onClick={()=>setSel(h)} style={{cursor:"pointer",padding:"16px 15px"}}>
          <div style={{fontSize:30,marginBottom:7}}>{h.emoji}</div>
          <div style={{fontFamily:"var(--fd)",fontWeight:800,fontSize:15,marginBottom:3}}>{h.name}</div>
          <Badge label={lvls[li]} color={h.color}/>
          <div style={{marginTop:9,marginBottom:5}}><Bar done={dc} total={Math.max(h.steps.length,1)} color={h.color} h={8}/></div>
          <div style={{fontSize:11,color:"var(--mu)"}}>{dc}/{h.steps.length} steg · Nivå {li+1}</div>
        </Card>;
      })}
    </div>
  </div>;
}
 
